INSERT INTO files (code, full_code, title, tags, inventory_id)
INSERT INTO file_years (file_id, start_year, end_year) SELECT f.id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int
INSERT INTO fond_years (fond_id, start_year, end_year) SELECT fo.id, fy.s, fy.e FROM fy JOIN fonds fo ON fo.code = fy.fond JOIN arch ON arch.id = fo.archive_id WHERE NOT EXISTS (SELECT 1 FROM fond_years y WHERE y.fond_id = fo.id) ON CONFLICT DO NOTHING;
INSERT INTO file_authors (file_id, author_id) SELECT g.dst_id, fa.author_id FROM file_authors fa JOIN g ON fa.file_id = g.src_id ON CONFLICT DO NOTHING; DELETE FROM file_authors fa USING g WHERE fa.file_id = g.src_id;
