BEGIN;
CREATE TEMP TABLE arch AS SELECT id FROM archives WHERE code = 'ДАХО';
DO $$ BEGIN IF (SELECT count(*) FROM arch) <> 1 THEN RAISE EXCEPTION 'archive not found'; END IF; END $$;

-- A. справи in the catalog but missing in the DB
CREATE TEMP TABLE mf(fond text, inv text, code text, title text, tags text[], years text);
SELECT mf.code, 'ДАХО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, mf.title, mf.tags, i.id
FROM mf JOIN fonds fo ON fo.code = mf.fond JOIN arch ON arch.id = fo.archive_id JOIN inventories i ON i.fond_id = fo.id AND i.code = mf.inv
WHERE NOT EXISTS (SELECT 1 FROM files x WHERE x.inventory_id = i.id AND x.code = mf.code);
FROM mf JOIN files f ON f.full_code = 'ДАХО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, unnest(string_to_array(mf.years, ',')) r
WHERE mf.years <> '' AND NOT EXISTS (SELECT 1 FROM file_years y WHERE y.file_id = f.id) ON CONFLICT DO NOTHING;
DO $$ BEGIN IF (SELECT count(*) FROM mf JOIN files f ON f.full_code = 'ДАХО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code) <> (SELECT count(*) FROM mf) THEN RAISE EXCEPTION 'A: not all files created (inventory missing?)'; END IF; END $$;

